import React, { useState } from 'react';
import { Send, Paperclip } from 'lucide-react';
import './Dashboard.css';
import Navbar from '../Components/Navbar';
import Sidebar from '../Components/Sidebar';
import FileUpload from '../Components/FileUpload';
import dashboardArrow from '../assets/dashboardarrow.svg';
import apitestingIcon from '../assets/apitestingicons.svg';
import guitestingIcon from '../assets/guitestingagent.svg';
import microphoneIcon from '../assets/Microphone.svg';

const Dashboard = () => {
  const [isUploadActive, setIsUploadActive] = useState(false);
  const [message, setMessage] = useState('');

  const features = {
    'API Testing Agent': [
      'Generate the test cases for on-boarding flow',
      'Generate and run the test cases from the given swagger file',
      'Generate and run the test cases from the given swagger file'
    ],
    'GUI Testing Agent': [
      'Generate and run the test cases from the given swagger file',
      'Generate and run the test cases from the given swagger file',
      'Generate and run the test cases from the given swagger file'
    ]
  };

  const FeatureCard = ({ title, items, icon }) => (
    <div className="feature-card">
      <div className="feature-header" data-type={title.toLowerCase().split(' ')[0]}>
        <img src={icon} alt={title} className="feature-icon" />
        <h3>{title}</h3>
      </div>
      <div className="feature-items">
        {items.map((item, index) => (
          <div key={index} className="feature-item">
            <span>{item}</span>
            <img src={dashboardArrow} alt="arrow" className="arrow-icon" />
          </div>
        ))}
      </div>
    </div>
  );

  const handleSendMessage = () => {
    if (message.trim()) {
      // Handle message sending logic here
      setMessage('');
    }
  };

  return (
    <div className="dashboard-container">
      <Navbar />
      <div className="main-content">
        <Sidebar />
        <div className={`dashboard-content ${isUploadActive ? 'upload-active' : ''}`}>
          {/* Overlay blocks for blur effect */}
          <div className="dashboard-overlay-block-1" />
          <div className="dashboard-overlay-block-2" />

          <div className="header">
            <h1 className="main-title">
              Unveiling the Power of Test Case Generation
              <br />
              and Execution
            </h1>
            <p className="subtitle">
              Software testing with automated case generation, execution, and meticulous scrutiny, 
              ensuring precision and efficiency in development workflows.
            </p>
          </div>

          <div className="features-section">
            <h2 className="features-title">Try out our Features</h2>
            <div className="features-grid">
              <FeatureCard
                title="API Testing Agent"
                items={features['API Testing Agent']}
                icon={apitestingIcon}
              />
              <FeatureCard
                title="GUI Testing Agent"
                items={features['GUI Testing Agent']}
                icon={guitestingIcon}
              />
            </div>

            <div className="chat-section">
              <div className="chat-input">
                <input
                  type="text"
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  placeholder="How can I help you?"
                  className="chat-textfield"
                />
                <div className="chat-actions">
                  <button 
                    className="action-button"
                    onClick={() => setIsUploadActive(true)}
                  >
                    <Paperclip size={20} />
                  </button>
                  <button className="action-button">
                    <img 
                      src={microphoneIcon} 
                      alt="microphone"
                      className="microphone-icon" 
                    />
                  </button>
                  <button 
                    className="send-button"
                    onClick={handleSendMessage}
                  >
                    <Send size={16} />
                    <span>Send</span>
                  </button>
                </div>
              </div>
            </div>
          </div>

          {/* File Upload Modal */}
          {isUploadActive && (
            <FileUpload onClose={() => setIsUploadActive(false)} />
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
